  Object.assign(english,{"Добавьте ключ Groq в разделе «Подключения».":"Add a Groq API key in Connections.","Добавьте ключ Groq для распознавания голоса.":"Add a Groq key for speech recognition.","Добавьте ключ Google Gemini в разделе «Подключения».":"Add a Google Gemini API key in Connections.","Добавьте ключ Google Gemini для распознавания голоса.":"Add a Google Gemini key for speech recognition.","Добавьте ключ Gemini в разделе «Подключения».":"Add a Gemini API key in Connections.","Добавьте ключ Gemini для распознавания голоса.":"Add a Gemini key for speech recognition.","Добавьте ключ OpenRouter в разделе «Подключения».":"Add a OpenRouter API key in Connections.","Добавьте ключ OpenRouter для распознавания голоса.":"Add a OpenRouter key for speech recognition."});
  let language='ru';
  const escapePattern=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const pattern=new RegExp(Object.keys(english).sort((a,b)=>b.length-a.length).map(escapePattern).join('|'),'g');
  // Translate source-code text fragments before interpolating user data.
  // Internal values keep their original identifiers in either language.
  function segment(source){
    if(language==='ru')return source;
    const values=[];
    const protectedSource=source.replace(/\b(value|data-filter)=(['"])(.*?)\2/g,match=>{values.push(match);return `__JEFFY_VALUE_${values.length-1}__`;});
    return protectedSource.replace(pattern,text=>english[text]).replace(/__JEFFY_VALUE_(\d+)__/g,(_,index)=>values[+index]);
  }
  function t(source){
    if(typeof source!=='string'||language==='ru')return source;
    if(english[source]!==undefined)return english[source];
    const trimmed=source.trim();if(english[trimmed]!==undefined)return source.replace(trimmed,english[trimmed]);
    return source;
  }
  function tr(parts,...values){return parts.map((part,index)=>segment(part)+(index<values.length?values[index]:'')).join('');}
  const staticText=new WeakMap(),staticAttributes=new WeakMap();
  function translateStatic(root){
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
    for(let node=walker.nextNode();node;node=walker.nextNode()){
      if(node.parentElement?.closest('script,style,input,textarea,code,kbd'))continue;
      if(!staticText.has(node))staticText.set(node,node.textContent);
      const source=staticText.get(node),trimmed=source.trim();node.textContent=source.replace(trimmed,t(trimmed));
    }
    for(const element of [root,...root.querySelectorAll('[title],[aria-label],[placeholder]')]){
      let attributes=staticAttributes.get(element);if(!attributes){attributes={};for(const name of ['title','aria-label','placeholder'])if(element.hasAttribute(name))attributes[name]=element.getAttribute(name);staticAttributes.set(element,attributes);}
      for(const [name,value] of Object.entries(attributes))element.setAttribute(name,t(value));
    }
  }
  function setLanguage(next){
    if(!['ru','en'].includes(next))throw Error('Unsupported interface language');language=next;
    if(typeof document!=='undefined'){
      document.documentElement.lang=language;
      for(const selector of ['.sidebar','.topbar','footer','.loading']){const root=document.querySelector(selector);if(root)translateStatic(root);}
      const select=document.querySelector('#ui-language');if(select)select.value=language;
    }
  }
  globalThis.I18n={t,tr,segment,setLanguage,getLanguage:()=>language,locale:()=>language==='en'?'en-US':'ru-RU'};
